multimap<int, char> mm;
mm.emplace(1, 'A');
mm.emplace(2, 'B');
mm.emplace(1, 'C');
mm.emplace(1, 'D'); // Key 1 has 3 elements

// Get start iterator (first element >= key)
auto low = mm.lower_bound(1);

// Get end iterator (first element > key)
auto high = mm.upper_bound(1);

// Get iterator pair defining the range [first, last)
auto range = mm.equal_range(1);

// Iterate the precise range using bounds
for (auto it = range.first; it != range.second; ++it) {
    // Access: it->first, it->second
}

// Low/High bounds define the same range
for (auto it = low; it != high; ++it) {}
